def get_version(path=None, module=None):
    """Return the version string.

    This uses the __version__ attribute of the module.

    """
    if path is None:
        path = os.path.dirname(os.path.abspath(__file__))
    if module is None:
        module = 'katversion'
    return get_module_attribute(path, module, '__version__')


def get_module_attribute(path, module, attribute):
    """Return the value of an attribute in a module.

    This is a helper function for get_version.

    """
    if path is None:
        path = os.path.dirname(os.path.abspath(__file__))
    module_path = os.path.join(path, module + '.py')
    with open(module_path, 'r') as f:
        for line in f:
            if line.startswith(attribute):
                return line.split()[-1].strip("'")
    raise AttributeError('Attribute %s not found in %s' % (attribute, module))


